package com.baonam.music; import android.app.*; import android.os.*; import android.media.*; import android.widget.*;
public class MainActivity extends Activity { MediaPlayer p; int[] ids={R.raw.ru_ngu,R.raw.chill,R.raw.neon_dream}; public void onCreate(Bundle b){super.onCreate(b); LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,40,32,20); TextView t=new TextView(this);t.setText("🎵 Nhạc Chill & Ru Ngủ");t.setTextSize(26);l.addView(t);String[] n={"🌙 Ru ngủ","🌌 Chill","💜 Neon Dream"};for(int i=0;i<3;i++){final int k=i;Button x=new Button(this);x.setText(n[i]);x.setOnClickListener(v->play(k));l.addView(x);}Button s=new Button(this);s.setText("⏹ Dừng");s.setOnClickListener(v->{if(p!=null){p.stop();p.release();p=null;}});l.addView(s);setContentView(l);}void play(int k){if(p!=null){p.stop();p.release();}p=MediaPlayer.create(this,ids[k]);p.setLooping(true);p.start();}}